<template><section class="special-tests-page"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error"><strong>No fue posible cargar los laboratorios de referencia.</strong><span>{{loadError}}</span></div><section class="bio-nexus-administrative-directory"><BioNexusDataGrid class="special-tests-grid" :row-data="rows" :column-defs="columnDefs" :default-col-def="defaultColDef" :components="gridComponents" :get-row-id="({data})=>String(data.id)" :quick-filter-text="searchText" search-enabled v-model:search-model-value="searchText" search-placeholder="Buscar laboratorio" refresh-enabled :refreshing="loading" :refresh-disabled="saving" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="300" :max-grid-height="560" @refresh="loadRows" @row-context-menu="openContextMenu"><template #actions><button v-if="canCreate" class="bio-nexus-action bio-nexus-action-primary" :disabled="loading||saving" @click="formDialog?.openCreate()"><BioNexusActionIcon action="create"/>Nuevo laboratorio</button></template></BioNexusDataGrid><BioNexusContextMenu ref="contextMenu" :open="context.open" :x="context.x" :y="context.y" :items="contextItems" @close="closeContext" @select="runContext"/></section><SpecialTestLabDialog ref="formDialog" :saving="saving" :can-create="canCreate" :can-update="canUpdate" :can-item-create="canItemCreate" :can-item-delete="canItemDelete" :exams="exams" @submit="saveForm"/><SpecialTestStateDialog ref="stateDialog" :saving="saving" @confirm="saveState"/></section></template>
<script setup>import{computed,nextTick,onMounted,ref}from'vue';import BioNexusDataGrid from'@/components/grid/BioNexusDataGrid.vue';import BioNexusGridActionsCell from'@/components/grid/BioNexusGridActionsCell.vue';import BioNexusGridToggleCell from'@/components/grid/BioNexusGridToggleCell.vue';import BioNexusOptionFilter from'@/components/grid/BioNexusOptionFilter.vue';import BioNexusActionIcon from'@/components/ui/BioNexusActionIcon.vue';import BioNexusContextMenu from'@/components/ui/BioNexusContextMenu.vue';import SpecialTestLabDialog from'@/components/specialtests/SpecialTestLabDialog.vue';import SpecialTestStateDialog from'@/components/specialtests/SpecialTestStateDialog.vue';import{getExamGroups,getExamsByGroup}from'@/services/examCatalogService';import{createSpecialTestItem,createSpecialTestLab,deleteSpecialTestItem,getSpecialTestLab,getSpecialTestLabs,specialTestsError,updateSpecialTestLab}from'@/services/specialTestsService';import{useAuthorizationStore}from'@/stores/authorization';import{useBioNexusToast}from'@/composables/useBioNexusToast';const authorization=useAuthorizationStore(),toast=useBioNexusToast(),rows=ref([]),exams=ref([]),loading=ref(false),saving=ref(false),loadError=ref(''),searchText=ref(''),formDialog=ref(null),stateDialog=ref(null),contextMenu=ref(null),context=ref({open:false,x:0,y:0,row:null});const canCreate=computed(()=>authorization.hasPermission('special-tests.create')),canUpdate=computed(()=>authorization.hasPermission('special-tests.update')),canState=computed(()=>authorization.hasPermission('special-tests.update')),canItemCreate=computed(()=>authorization.hasPermission('special-tests.update')),canItemDelete=computed(()=>authorization.hasPermission('special-tests.update'));const defaultColDef=Object.freeze({sortable:true,filter:true,resizable:true,suppressHeaderMenuButton:true}),gridComponents=Object.freeze({BioNexusGridActionsCell,BioNexusGridToggleCell});const columnDefs=computed(()=>[{field:'description',headerName:'Nombre',minWidth:220,flex:1},{field:'address',headerName:'Direccion',minWidth:260,flex:1.3},{field:'email',headerName:'Correo',minWidth:220,flex:1},{field:'itemCount',headerName:'Pruebas',width:110},{field:'isActive',headerName:'Estado',width:160,filter:BioNexusOptionFilter,filterParams:{options:[{value:true,label:'Activo'},{value:false,label:'Inactivo'}]},cellRenderer:BioNexusGridToggleCell,cellRendererParams:{disabled:()=>!canState.value||saving.value,onToggle:r=>stateDialog.value?.open(r)}},{colId:'actions',headerName:'Acciones',width:110,pinned:'right',sortable:false,filter:false,resizable:false,cellRenderer:BioNexusGridActionsCell,cellRendererParams:{actions:[{key:'edit',label:'Editar',visible:()=>canUpdate.value||canItemCreate.value||canItemDelete.value,disabled:()=>saving.value,onClick:openEdit}]}}]);const contextItems=computed(()=>{const r=context.value.row;return r?[{key:'edit',label:'Editar',visible:canUpdate.value||canItemCreate.value||canItemDelete.value,action:()=>openEdit(r)},{key:'state',label:r.annulled?'Activar laboratorio':'Inactivar laboratorio',icon:r.annulled?'activate':'deactivate',visible:canState.value,action:()=>stateDialog.value?.open(r)}]:[]});function replaceRow(saved){const next=rows.value.map(row=>row.id===saved.id?saved:row);if(!next.some(row=>row.id===saved.id))next.push(saved);rows.value=next.sort((a,b)=>a.description.localeCompare(b.description,'es'))}
async function loadRows(){if(loading.value||saving.value)return;loading.value=true;loadError.value='';try{const[loaded,groups]=await Promise.all([getSpecialTestLabs(),getExamGroups()]);rows.value=loaded;exams.value=(await Promise.all(groups.map(g=>getExamsByGroup(g.id)))).flat().sort((a,b)=>a.description.localeCompare(b.description,'es'))}catch(e){rows.value=[];loadError.value=specialTestsError(e,'No fue posible consultar los laboratorios de referencia.');toast.error(loadError.value)}finally{loading.value=false}}async function openEdit(row){try{formDialog.value?.openEdit(await getSpecialTestLab(row.id))}catch(e){toast.error(specialTestsError(e,'No fue posible consultar el laboratorio.'))}}async function saveForm(p){if(saving.value)return;saving.value=true;formDialog.value?.clearError();try{const lab=p.mode==='create'?await createSpecialTestLab({...p.values,examIds:p.items.map(item=>item.exam_list_Id)}):p.labChanged?await updateSpecialTestLab(p.record.id,p.values):p.record;if(p.mode!=='create'){const original=new Map((p.record.specialTestItems||[]).map(x=>[x.exam_list_Id,x])),next=new Map(p.items.map(x=>[x.exam_list_Id,x]));for(const item of original.values())if(!next.has(item.exam_list_Id))await deleteSpecialTestItem(item.id);for(const item of next.values())if(!original.has(item.exam_list_Id))await createSpecialTestItem({...item,specialTestLabId:lab.id})}formDialog.value?.close();toast.success(p.mode==='create'?'Laboratorio creado correctamente.':'Laboratorio actualizado correctamente.');saving.value=false;await loadRows()}catch(e){formDialog.value?.setError(specialTestsError(e,'No fue posible guardar el laboratorio.'))}finally{saving.value=false}}async function saveState(row){saving.value=true;try{const saved=await updateSpecialTestLab(row.id,{annulled:!row.annulled});if(!saved)throw new Error('El Backend no devolvió un laboratorio válido.');replaceRow(saved);stateDialog.value?.close();toast.success(row.annulled?'Laboratorio activado.':'Laboratorio inactivado.')}catch(e){stateDialog.value?.setError(specialTestsError(e,'No fue posible cambiar el estado.'))}finally{saving.value=false}}async function openContextMenu({event,row}){context.value={open:true,x:event.clientX,y:event.clientY,row};await nextTick();contextMenu.value?.positionMenu?.()}function closeContext(){context.value={open:false,x:0,y:0,row:null}}async function runContext(item){const action=item?.action;closeContext();if(typeof action==='function')await action()}onMounted(loadRows)</script>
<style scoped>.special-tests-page,.special-tests-grid{min-width:0}.special-tests-grid :deep(.bio-nexus-grid-actions-cell),.special-tests-grid :deep(.bio-nexus-grid-actions-header .ag-header-cell-label){justify-content:center}</style>
